package com.medicare360.patient; import jakarta.persistence.*; @Entity public class Patient { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; private String email; private String phone; private String dateOfBirth; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(String v){dateOfBirth=v;} }